export const mediaFiles = pgTable(
  'media_files',
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    tenantId: uuid('tenant_id').notNull(),
    kind: text().notNull(),
    bucket: text().notNull(),
    path: text().notNull(),
    // You can use { mode: "bigint" } if numbers are exceeding js number limitations
    bytes: bigint({ mode: 'number' }).notNull(),
    mime: text().notNull(),
    width: integer(),
    height: integer(),
    uploadedBy: uuid('uploaded_by'),
    countsTowardLimit: boolean('counts_toward_limit').generatedAlwaysAs(
      sql`(kind <> 'plan_proof'::text)`,
    ),
    confirmedAt: timestamp('confirmed_at', { withTimezone: true, mode: 'string' }),
    deletedAt: timestamp('deleted_at', { withTimezone: true, mode: 'string' }),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    check(
      'media_files_bucket_check',
      sql`bucket = ANY (ARRAY['menu'::text, 'look'::text, 'qr'::text, 'profile'::text, 'proofs'::text, 'plan-proofs'::text])`,
    ),
    check('media_files_bytes_check', sql`bytes >= 0`),
    check('media_files_check', sql`CHECK (starts_with(path, ((tenant_id)::text || '/'::text)`),
    check('media_files_height_check', sql`height > 0`),
    check(
      'media_files_kind_check',
      sql`kind = ANY (ARRAY['logo'::text, 'banner'::text, 'item'::text, 'category'::text, 'qr'::text, 'avatar'::text, 'plan_proof'::text, 'proof'::text, 'member_photo'::text, 'news_photo'::text])`,
    ),
    check(
      'media_files_mime_check',
      sql`mime = ANY (ARRAY['image/webp'::text, 'image/jpeg'::text, 'image/png'::text, 'image/gif'::text])`,
    ),
    check('media_files_path_check', sql`(char_length(path) >= 3) AND (char_length(path) <= 300)`),
    check('media_files_width_check', sql`width > 0`),
    foreignKey({
      columns: [table.tenantId],
      foreignColumns: [tenants.id],
      name: 'media_files_tenant_id_fkey',
    }).onDelete('cascade'),
    foreignKey({
      columns: [table.uploadedBy],
      foreignColumns: [authUsers.id],
      name: 'media_files_uploaded_by_fkey',
    }).onDelete('set null'),
    index('media_files_tenant_kind')
      .using(
        'btree',
        table.tenantId.asc().nullsLast().op('uuid_ops'),
        table.kind.asc().nullsLast().op('text_ops'),
      )
      .where(sql`(deleted_at IS NULL)`),
    index('media_files_unconfirmed')
      .using('btree', table.createdAt.asc().nullsLast().op('timestamptz_ops'))
      .where(sql`((confirmed_at IS NULL) AND (deleted_at IS NULL))`),
    index('media_files_uploaded_by').using(
      'btree',
      table.uploadedBy.asc().nullsLast().op('uuid_ops'),
    ),
    unique('media_files_path_key').on(table.path),
    unique('media_files_tenant_id_id_key').on(table.id, table.tenantId),
  ],
);

