export const orders = pgTable(
  'orders',
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    tenantId: uuid('tenant_id').notNull(),
    businessDate: date('business_date').notNull(),
    orderNo: integer('order_no').notNull(),
    token: text().notNull(),
    pickupCode: text('pickup_code').notNull(),
    clientKey: text('client_key'),
    type: text().notNull(),
    status: text().default('placed').notNull(),
    paymentMethod: text('payment_method').notNull(),
    paymentStatus: text('payment_status').default('unpaid').notNull(),
    paymentAccountId: uuid('payment_account_id'),
    memberId: uuid('member_id'),
    customerName: text('customer_name').notNull(),
    customerPhone: text('customer_phone'),
    customerEmail: text('customer_email'),
    addressLine: text('address_line'),
    houseNo: text('house_no'),
    floor: text(),
    landmark: text(),
    lat: doublePrecision(),
    lng: doublePrecision(),
    zoneId: uuid('zone_id'),
    distanceM: integer('distance_m'),
    placedAt: timestamp('placed_at', { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
    scheduledAt: timestamp('scheduled_at', { withTimezone: true, mode: 'string' }),
    dueAt: timestamp('due_at', { withTimezone: true, mode: 'string' }).notNull(),
    startBy: timestamp('start_by', { withTimezone: true, mode: 'string' }).notNull(),
    payBy: timestamp('pay_by', { withTimezone: true, mode: 'string' }),
    subtotal: integer().notNull(),
    discount: integer().default(0).notNull(),
    deliveryFee: integer('delivery_fee').default(0).notNull(),
    total: integer().notNull(),
    rewardTitle: text('reward_title'),
    note: text(),
    ownerNote: text('owner_note'),
    seenAt: timestamp('seen_at', { withTimezone: true, mode: 'string' }),
    lastStepAt: timestamp('last_step_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
    riderName: text('rider_name'),
    riderPhone: text('rider_phone'),
    riderProvider: text('rider_provider'),
    trackingUrl: text('tracking_url'),
    refundAmount: integer('refund_amount'),
    refundReason: text('refund_reason'),
    refundedAt: timestamp('refunded_at', { withTimezone: true, mode: 'string' }),
    cancelReason: text('cancel_reason'),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
    source: text().default('storefront').notNull(),
    paidAmount: integer('paid_amount').default(0).notNull(),
    version: integer().default(1).notNull(),
    editedAt: timestamp('edited_at', { withTimezone: true, mode: 'string' }),
  },
  (table) => [
    check(
      'orders_address_line_check',
      sql`(char_length(address_line) >= 1) AND (char_length(address_line) <= 160)`,
    ),
    check(
      'orders_cancel_reason_check',
      sql`(char_length(cancel_reason) >= 1) AND (char_length(cancel_reason) <= 200)`,
    ),
    check('orders_check', sql`total = ((subtotal - discount) + delivery_fee)`),
    check('orders_check1', sql`discount <= subtotal`),
    check('orders_check10', sql`start_by <= due_at`),
    check(
      'orders_check2',
      sql`(type = 'delivery'::text) OR ((address_line IS NULL) AND (delivery_fee = 0))`,
    ),
    check('orders_check3', sql`(type <> 'delivery'::text) OR (address_line IS NOT NULL)`),
    check('orders_check4', sql`(lat IS NULL) = (lng IS NULL)`),
    check(
      'orders_check5',
      sql`(pay_by IS NULL) OR (payment_method = ANY (ARRAY['gcash'::text, 'maya'::text, 'bank'::text, 'qr_ph'::text]))`,
    ),
    check('orders_check6', sql`(status <> 'cancelled'::text) OR (cancel_reason IS NOT NULL)`),
    check(
      'orders_check7',
      sql`((refund_amount IS NULL) = (refunded_at IS NULL)) AND ((refund_amount IS NULL) = (refund_reason IS NULL))`,
    ),
    check('orders_check8', sql`(payment_status = 'refunded'::text) = (refunded_at IS NOT NULL)`),
    check('orders_check9', sql`(refund_amount IS NULL) OR (refund_amount <= total)`),
    check(
      'orders_client_key_check',
      sql`(char_length(client_key) >= 8) AND (char_length(client_key) <= 64)`,
    ),
    check(
      'orders_customer_email_check',
      sql`(char_length(customer_email) >= 3) AND (char_length(customer_email) <= 254)`,
    ),
    check(
      'orders_customer_name_check',
      sql`(char_length(customer_name) >= 1) AND (char_length(customer_name) <= 80)`,
    ),
    check(
      'orders_customer_phone_check',
      sql`(char_length(customer_phone) >= 1) AND (char_length(customer_phone) <= 20)`,
    ),
    check('orders_delivery_fee_check', sql`delivery_fee >= 0`),
    check('orders_discount_check', sql`discount >= 0`),
    check('orders_distance_m_check', sql`distance_m >= 0`),
    check('orders_floor_check', sql`char_length(floor) <= 40`),
    check('orders_house_no_check', sql`char_length(house_no) <= 40`),
    check('orders_landmark_check', sql`char_length(landmark) <= 120`),
    check(
      'orders_lat_check',
      sql`(lat >= ('-90'::integer)::double precision) AND (lat <= (90)::double precision)`,
    ),
    check(
      'orders_lng_check',
      sql`(lng >= ('-180'::integer)::double precision) AND (lng <= (180)::double precision)`,
    ),
    check('orders_note_check', sql`char_length(note) <= 240`),
    check('orders_order_no_check', sql`order_no >= 1`),
    check('orders_owner_note_check', sql`char_length(owner_note) <= 300`),
    check('orders_paid_amount_check', sql`paid_amount >= 0`),
    check(
      'orders_payment_method_check',
      sql`payment_method = ANY (ARRAY['cash'::text, 'cod'::text, 'gcash'::text, 'maya'::text, 'bank'::text, 'qr_ph'::text])`,
    ),
    check(
      'orders_payment_status_check',
      sql`payment_status = ANY (ARRAY['unpaid'::text, 'pending'::text, 'paid'::text, 'refunded'::text])`,
    ),
    check('orders_pickup_code_check', sql`pickup_code ~ '^[2-9A-HJKMNP-Z]{4}$'::text`),
    check('orders_refund_amount_check', sql`refund_amount >= 0`),
    check(
      'orders_refund_reason_check',
      sql`(char_length(refund_reason) >= 1) AND (char_length(refund_reason) <= 200)`,
    ),
    check('orders_reward_title_check', sql`char_length(reward_title) <= 60`),
    check(
      'orders_rider_name_check',
      sql`(char_length(rider_name) >= 1) AND (char_length(rider_name) <= 60)`,
    ),
    check(
      'orders_rider_phone_check',
      sql`(char_length(rider_phone) >= 1) AND (char_length(rider_phone) <= 20)`,
    ),
    check('orders_rider_provider_check', sql`char_length(rider_provider) <= 40`),
    check('orders_source_check', sql`source = ANY (ARRAY['storefront'::text, 'owner'::text])`),
    check(
      'orders_status_check',
      sql`status = ANY (ARRAY['placed'::text, 'preparing'::text, 'ready'::text, 'out_for_delivery'::text, 'completed'::text, 'cancelled'::text, 'expired'::text])`,
    ),
    check('orders_subtotal_check', sql`subtotal >= 0`),
    check('orders_token_check', sql`(char_length(token) >= 16) AND (char_length(token) <= 64)`),
    check('orders_total_check', sql`total >= 0`),
    check('orders_tracking_url_check', sql`char_length(tracking_url) <= 500`),
    check(
      'orders_type_check',
      sql`type = ANY (ARRAY['walk_in'::text, 'pickup'::text, 'delivery'::text])`,
    ),
    check('orders_version_check', sql`version >= 1`),
    foreignKey({
      columns: [table.memberId, table.tenantId],
      foreignColumns: [members.id, members.tenantId],
      name: 'orders_tenant_id_member_id_fkey',
    }).onDelete('set null'),
    foreignKey({
      columns: [table.paymentAccountId, table.tenantId],
      foreignColumns: [paymentAccounts.id, paymentAccounts.tenantId],
      name: 'orders_tenant_id_payment_account_id_fkey',
    }).onDelete('restrict'),
    foreignKey({
      columns: [table.tenantId, table.zoneId],
      foreignColumns: [deliveryZones.id, deliveryZones.tenantId],
      name: 'orders_tenant_id_zone_id_fkey',
    }).onDelete('set null'),
    foreignKey({
      columns: [table.tenantId],
      foreignColumns: [tenants.id],
      name: 'orders_tenant_id_fkey',
    }).onDelete('cascade'),
    index('orders_member').using('btree', table.memberId.asc().nullsLast().op('uuid_ops')),
    index('orders_payment_account').using(
      'btree',
      table.paymentAccountId.asc().nullsLast().op('uuid_ops'),
    ),
    index('orders_tenant_day').using(
      'btree',
      table.tenantId.asc().nullsLast().op('date_ops'),
      table.businessDate.asc().nullsLast().op('uuid_ops'),
    ),
    index('orders_tenant_member')
      .using(
        'btree',
        table.tenantId.asc().nullsLast().op('uuid_ops'),
        table.memberId.asc().nullsLast().op('uuid_ops'),
        table.placedAt.desc().nullsFirst().op('timestamptz_ops'),
      )
      .where(sql`(member_id IS NOT NULL)`),
    index('orders_tenant_open')
      .using(
        'btree',
        table.tenantId.asc().nullsLast().op('text_ops'),
        table.status.asc().nullsLast().op('text_ops'),
      )
      .where(
        sql`(status = ANY (ARRAY['placed'::text, 'preparing'::text, 'ready'::text, 'out_for_delivery'::text]))`,
      ),
    index('orders_tenant_phone').using(
      'btree',
      table.tenantId.asc().nullsLast().op('text_ops'),
      table.customerPhone.asc().nullsLast().op('timestamptz_ops'),
      table.placedAt.desc().nullsFirst().op('text_ops'),
    ),
    index('orders_tenant_pickup_code').using(
      'btree',
      table.tenantId.asc().nullsLast().op('uuid_ops'),
      table.pickupCode.asc().nullsLast().op('text_ops'),
    ),
    index('orders_tenant_scheduled')
      .using(
        'btree',
        table.tenantId.asc().nullsLast().op('timestamptz_ops'),
        table.scheduledAt.asc().nullsLast().op('uuid_ops'),
      )
      .where(sql`(scheduled_at IS NOT NULL)`),
    index('orders_unpaid_pay_by')
      .using('btree', table.payBy.asc().nullsLast().op('timestamptz_ops'))
      .where(sql`((payment_status = 'unpaid'::text) AND (status = 'placed'::text))`),
    index('orders_zone').using('btree', table.zoneId.asc().nullsLast().op('uuid_ops')),
    unique('orders_tenant_id_business_date_order_no_key').on(
      table.tenantId,
      table.businessDate,
      table.orderNo,
    ),
    unique('orders_tenant_id_client_key_key').on(table.tenantId, table.clientKey),
    unique('orders_tenant_id_id_key').on(table.id, table.tenantId),
    unique('orders_token_key').on(table.token),
  ],
);

