    index('push_campaigns_created_by').using(
      'btree',
      table.createdBy.asc().nullsLast().op('uuid_ops'),
    ),
    index('push_campaigns_due')
      .using('btree', sql`tenant_id`, sql`COALESCE(sent_at, send_at)`)
