export const shopSettings = pgTable(
  'shop_settings',
  {
    tenantId: uuid('tenant_id').primaryKey().notNull(),
    phone: text(),
    messengerUsername: text('messenger_username'),
    facebookUrl: text('facebook_url'),
    googleReviewUrl: text('google_review_url'),
    address: text(),
    showAddress: boolean('show_address').default(true).notNull(),
    pinLat: doublePrecision('pin_lat'),
    pinLng: doublePrecision('pin_lng'),
    pickupNote: text('pickup_note'),
    walkInOn: boolean('walk_in_on').default(true).notNull(),
    pickupOn: boolean('pickup_on').default(true).notNull(),
    deliveryOn: boolean('delivery_on').default(false).notNull(),
    daysAhead: integer('days_ahead').default(3).notNull(),
    slotMinutes: integer('slot_minutes').default(30).notNull(),
    ordersPerSlot: integer('orders_per_slot'),
    prepMinutes: integer('prep_minutes').default(20).notNull(),
    takeOrdersWhileClosed: boolean('take_orders_while_closed').default(true).notNull(),
    codMaxTotal: integer('cod_max_total'),
    freeDeliveryFrom: integer('free_delivery_from'),
    busyUntil: timestamp('busy_until', { withTimezone: true, mode: 'string' }),
    paused: boolean().default(false).notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
    pushStampAdded: boolean('push_stamp_added').default(true).notNull(),
    pushRewardReady: boolean('push_reward_ready').default(true).notNull(),
  },
  (table) => [
    check(
      'shop_settings_address_check',
      sql`(char_length(address) >= 1) AND (char_length(address) <= 200)`,
    ),
    check('shop_settings_check', sql`walk_in_on OR pickup_on OR delivery_on`),
    check('shop_settings_check1', sql`(pin_lat IS NULL) = (pin_lng IS NULL)`),
    check('shop_settings_cod_max_total_check', sql`cod_max_total >= 0`),
    check('shop_settings_days_ahead_check', sql`(days_ahead >= 1) AND (days_ahead <= 60)`),
    check('shop_settings_facebook_url_check', sql`char_length(facebook_url) <= 200`),
    check('shop_settings_free_delivery_from_check', sql`free_delivery_from >= 0`),
    check('shop_settings_google_review_url_check', sql`char_length(google_review_url) <= 300`),
    check(
      'shop_settings_messenger_username_check',
      sql`(char_length(messenger_username) >= 1) AND (char_length(messenger_username) <= 100)`,
    ),
    check(
      'shop_settings_orders_per_slot_check',
      sql`(orders_per_slot >= 1) AND (orders_per_slot <= 50)`,
    ),
    check(
      'shop_settings_phone_check',
      sql`(char_length(phone) >= 1) AND (char_length(phone) <= 20)`,
    ),
    check('shop_settings_pickup_note_check', sql`char_length(pickup_note) <= 200`),
    check(
      'shop_settings_pin_lat_check',
      sql`(pin_lat >= ('-90'::integer)::double precision) AND (pin_lat <= (90)::double precision)`,
    ),
    check(
      'shop_settings_pin_lng_check',
      sql`(pin_lng >= ('-180'::integer)::double precision) AND (pin_lng <= (180)::double precision)`,
    ),
    check('shop_settings_prep_minutes_check', sql`(prep_minutes >= 5) AND (prep_minutes <= 180)`),
    check('shop_settings_slot_minutes_check', sql`slot_minutes = ANY (ARRAY[15, 30, 60])`),
    foreignKey({
      columns: [table.tenantId],
      foreignColumns: [tenants.id],
      name: 'shop_settings_tenant_id_fkey',
    }).onDelete('cascade'),
  ],
);

