export const stampCards = pgTable(
  'stamp_cards',
  {
    tenantId: uuid('tenant_id').primaryKey().notNull(),
    status: text().default('off').notNull(),
    minOrderTotal: integer('min_order_total').default(0).notNull(),
    stampsNeeded: integer('stamps_needed').default(8).notNull(),
    welcomeStamps: smallint('welcome_stamps').default(1).notNull(),
    maxEarned: integer('max_earned').default(1),
    period: text().default('day'),
    rewardKind: text('reward_kind').notNull(),
    rewardAmount: integer('reward_amount'),
    rewardItemId: uuid('reward_item_id'),
    rewardVariantId: uuid('reward_variant_id'),
    rewardTitle: text('reward_title').notNull(),
    rewardDescription: text('reward_description'),
    rewardMediaId: uuid('reward_media_id'),
    quantityTotal: integer('quantity_total'),
    quantityLeft: integer('quantity_left'),
    onePerCustomer: boolean('one_per_customer').default(false).notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    check('stamp_cards_check', sql`(max_earned IS NULL) = (period IS NULL)`),
    check(
      'stamp_cards_check1',
      sql`(reward_kind <> 'discount'::text) OR (reward_amount IS NOT NULL)`,
    ),
    check(
      'stamp_cards_check2',
      sql`(reward_kind = 'free_item'::text) = (reward_item_id IS NOT NULL)`,
    ),
    check('stamp_cards_check3', sql`(reward_item_id IS NULL) = (reward_variant_id IS NULL)`),
    check('stamp_cards_check4', sql`(quantity_total IS NULL) = (quantity_left IS NULL)`),
    check('stamp_cards_check5', sql`(quantity_left IS NULL) OR (quantity_left <= quantity_total)`),
    check('stamp_cards_max_earned_check', sql`(max_earned >= 1) AND (max_earned <= 10)`),
    check('stamp_cards_min_order_total_check', sql`min_order_total >= 0`),
    check(
      'stamp_cards_period_check',
      sql`period = ANY (ARRAY['day'::text, 'week'::text, 'month'::text])`,
    ),
    check('stamp_cards_quantity_left_check', sql`quantity_left >= 0`),
    check('stamp_cards_quantity_total_check', sql`quantity_total >= 1`),
    check('stamp_cards_reward_amount_check', sql`reward_amount > 0`),
    check('stamp_cards_reward_description_check', sql`char_length(reward_description) <= 200`),
    check(
      'stamp_cards_reward_kind_check',
      sql`reward_kind = ANY (ARRAY['discount'::text, 'free_item'::text, 'custom'::text])`,
    ),
    check(
      'stamp_cards_reward_title_check',
      sql`(char_length(reward_title) >= 1) AND (char_length(reward_title) <= 60)`,
    ),
    check('stamp_cards_stamps_needed_check', sql`(stamps_needed >= 4) AND (stamps_needed <= 20)`),
    check(
      'stamp_cards_status_check',
      sql`status = ANY (ARRAY['off'::text, 'on'::text, 'paused'::text])`,
    ),
    check('stamp_cards_welcome_stamps_check', sql`welcome_stamps = ANY (ARRAY[0, 1])`),
    foreignKey({
      columns: [table.rewardItemId, table.rewardVariantId, table.tenantId],
      foreignColumns: [itemVariants.id, itemVariants.itemId, itemVariants.tenantId],
      name: 'stamp_cards_reward_variant_fk',
    }).onDelete('restrict'),
    foreignKey({
      columns: [table.rewardItemId, table.tenantId],
      foreignColumns: [items.id, items.tenantId],
      name: 'stamp_cards_reward_item_fk',
    }).onDelete('restrict'),
    foreignKey({
      columns: [table.rewardMediaId, table.tenantId],
      foreignColumns: [mediaFiles.id, mediaFiles.tenantId],
      name: 'stamp_cards_tenant_id_reward_media_id_fkey',
    }).onDelete('set null'),
    foreignKey({
      columns: [table.tenantId],
      foreignColumns: [tenants.id],
      name: 'stamp_cards_tenant_id_fkey',
    }).onDelete('cascade'),
    index('stamp_cards_reward_item').using(
      'btree',
      table.rewardItemId.asc().nullsLast().op('uuid_ops'),
    ),
    index('stamp_cards_reward_media').using(
      'btree',
      table.rewardMediaId.asc().nullsLast().op('uuid_ops'),
    ),
    index('stamp_cards_reward_variant').using(
      'btree',
      table.rewardVariantId.asc().nullsLast().op('uuid_ops'),
    ),
  ],
);

export const stampEntries = pgTable(
  'stamp_entries',
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    tenantId: uuid('tenant_id').notNull(),
    memberId: uuid('member_id').notNull(),
    kind: text().notNull(),
    delta: integer().notNull(),
    reasonCategory: text('reason_category'),
    privateNote: text('private_note'),
    orderId: uuid('order_id'),
    claimId: uuid('claim_id'),
    undoesId: uuid('undoes_id'),
    clientKey: text('client_key'),
    byUserId: uuid('by_user_id'),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    check(
      'stamp_entries_check',
      sql`(kind <> ALL (ARRAY['welcome'::text, 'earned'::text, 'returned'::text, 'given'::text])) OR (delta > 0)`,
    ),
    check(
      'stamp_entries_check1',
      sql`(kind <> ALL (ARRAY['used'::text, 'claimed'::text, 'reversed'::text, 'removed'::text])) OR (delta < 0)`,
    ),
    check(
      'stamp_entries_check2',
      sql`(kind = ANY (ARRAY['given'::text, 'removed'::text])) = (reason_category IS NOT NULL)`,
    ),
    check(
      'stamp_entries_check3',
      sql`(private_note IS NULL) OR (kind = ANY (ARRAY['given'::text, 'removed'::text]))`,
    ),
    check('stamp_entries_check4', sql`(kind = 'undone'::text) = (undoes_id IS NOT NULL)`),
    check('stamp_entries_check5', sql`(kind <> 'earned'::text) OR (order_id IS NOT NULL)`),
    check('stamp_entries_check6', sql`(kind <> 'claimed'::text) OR (claim_id IS NOT NULL)`),
    check(
      'stamp_entries_client_key_check',
      sql`(char_length(client_key) >= 8) AND (char_length(client_key) <= 64)`,
    ),
    check(
      'stamp_entries_delta_check',
      sql`((delta >= '-50'::integer) AND (delta <= 50)) AND (delta <> 0)`,
    ),
    check(
      'stamp_entries_kind_check',
      sql`kind = ANY (ARRAY['welcome'::text, 'earned'::text, 'used'::text, 'claimed'::text, 'returned'::text, 'reversed'::text, 'given'::text, 'removed'::text, 'undone'::text])`,
    ),
    check(
      'stamp_entries_private_note_check',
      sql`(char_length(private_note) >= 1) AND (char_length(private_note) <= 200)`,
    ),
    check(
      'stamp_entries_reason_category_check',
      sql`reason_category = ANY (ARRAY['counter_purchase'::text, 'correction'::text, 'goodwill'::text, 'other'::text])`,
    ),
    foreignKey({
      columns: [table.byUserId],
      foreignColumns: [authUsers.id],
      name: 'stamp_entries_by_user_id_fkey',
    }).onDelete('set null'),
    foreignKey({
      columns: [table.claimId, table.tenantId],
      foreignColumns: [rewardClaims.id, rewardClaims.tenantId],
      name: 'stamp_entries_tenant_id_claim_id_fkey',
    }).onDelete('set null'),
    foreignKey({
      columns: [table.memberId, table.tenantId],
      foreignColumns: [members.id, members.tenantId],
      name: 'stamp_entries_tenant_id_member_id_fkey',
    }).onDelete('cascade'),
    foreignKey({
      columns: [table.orderId, table.tenantId],
      foreignColumns: [orders.id, orders.tenantId],
      name: 'stamp_entries_tenant_id_order_id_fkey',
    }).onDelete('set null'),
    foreignKey({
      columns: [table.tenantId, table.undoesId],
      foreignColumns: [table.id, table.tenantId],
      name: 'stamp_entries_tenant_id_undoes_id_fkey',
    }).onDelete('cascade'),
    foreignKey({
      columns: [table.tenantId],
      foreignColumns: [tenants.id],
      name: 'stamp_entries_tenant_id_fkey',
    }).onDelete('cascade'),
    index('stamp_entries_by_user').using('btree', table.byUserId.asc().nullsLast().op('uuid_ops')),
    index('stamp_entries_claim').using('btree', table.claimId.asc().nullsLast().op('uuid_ops')),
    index('stamp_entries_member_id').using(
      'btree',
      table.memberId.asc().nullsLast().op('uuid_ops'),
    ),
    index('stamp_entries_member').using(
      'btree',
      table.tenantId.asc().nullsLast().op('timestamptz_ops'),
      table.memberId.asc().nullsLast().op('timestamptz_ops'),
      table.createdAt.asc().nullsLast().op('timestamptz_ops'),
    ),
    index('stamp_entries_order').using('btree', table.orderId.asc().nullsLast().op('uuid_ops')),
    unique('stamp_entries_tenant_id_id_key').on(table.id, table.tenantId),
    uniqueIndex('stamp_entries_client_key')
      .using(
        'btree',
        table.tenantId.asc().nullsLast().op('text_ops'),
        table.clientKey.asc().nullsLast().op('uuid_ops'),
      )
      .where(sql`(client_key IS NOT NULL)`),
    uniqueIndex('stamp_entries_earned')
      .using('btree', table.orderId.asc().nullsLast().op('uuid_ops'))
      .where(sql`(kind = 'earned'::text)`),
    uniqueIndex('stamp_entries_undoes')
      .using('btree', table.undoesId.asc().nullsLast().op('uuid_ops'))
      .where(sql`(undoes_id IS NOT NULL)`),
    uniqueIndex('stamp_entries_used')
      .using('btree', table.orderId.asc().nullsLast().op('uuid_ops'))
      .where(sql`(kind = 'used'::text)`),
    uniqueIndex('stamp_entries_welcome')
      .using('btree', table.memberId.asc().nullsLast().op('uuid_ops'))
      .where(sql`(kind = 'welcome'::text)`),
  ],
);

