export const tenants = pgTable(
  'tenants',
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    slug: text().notNull(),
    name: text().notNull(),
    kind: text().notNull(),
    stage: text().default('setting_up').notNull(),
    city: text().default('').notNull(),
    facebookPage: text('facebook_page'),
    channel: text().default('direct').notNull(),
    campaign: text(),
    isDemo: boolean('is_demo').default(false).notNull(),
    priceMonthly: integer('price_monthly').notNull(),
    // You can use { mode: "bigint" } if numbers are exceeding js number limitations
    storageLimitBytes: bigint('storage_limit_bytes', { mode: 'number' })
      .default(524288000)
      .notNull(),
    trialEndsAt: timestamp('trial_ends_at', { withTimezone: true, mode: 'string' }),
    paidUntil: date('paid_until'),
    askedAt: timestamp('asked_at', { withTimezone: true, mode: 'string' }),
    liveAt: timestamp('live_at', { withTimezone: true, mode: 'string' }),
    remindedAt: timestamp('reminded_at', { withTimezone: true, mode: 'string' }),
    closesOn: date('closes_on'),
    closeReason: text('close_reason'),
    closedAt: timestamp('closed_at', { withTimezone: true, mode: 'string' }),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    check('tenants_campaign_check', sql`char_length(campaign) <= 100`),
    check(
      'tenants_channel_check',
      sql`channel = ANY (ARRAY['facebook_ad'::text, 'link'::text, 'direct'::text])`,
    ),
    check(
      'tenants_check',
      sql`(stage <> ALL (ARRAY['asked'::text, 'live'::text])) OR (asked_at IS NOT NULL)`,
    ),
    check('tenants_check1', sql`(stage <> 'live'::text) OR (live_at IS NOT NULL)`),
    check(
      'tenants_check2',
      sql`(stage <> 'closed'::text) OR ((closed_at IS NOT NULL) AND (close_reason IS NOT NULL))`,
    ),
    check('tenants_city_check', sql`char_length(city) <= 60`),
    check(
      'tenants_close_reason_check',
      sql`close_reason = ANY (ARRAY['not_paying'::text, 'owner_asked'::text, 'duplicate'::text, 'not_real'::text, 'other'::text])`,
    ),
    check('tenants_facebook_page_check', sql`char_length(facebook_page) <= 200`),
    check('tenants_kind_check', sql`kind = ANY (ARRAY['food'::text, 'retail'::text])`),
    check('tenants_name_check', sql`(char_length(name) >= 1) AND (char_length(name) <= 60)`),
    check('tenants_price_monthly_check', sql`price_monthly >= 100`),
    check(
      'tenants_slug_check',
      sql`(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text) AND ((char_length(slug) >= 3) AND (char_length(slug) <= 40))`,
    ),
    check(
      'tenants_stage_check',
      sql`stage = ANY (ARRAY['setting_up'::text, 'asked'::text, 'live'::text, 'closed'::text])`,
    ),
    check('tenants_storage_limit_bytes_check', sql`storage_limit_bytes > 0`),
    index('tenants_stage').using('btree', table.stage.asc().nullsLast().op('text_ops')),
    unique('tenants_slug_key').on(table.slug),
  ],
);

export const trackEvents = pgTable(
  'track_events',
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    eventId: text('event_id').notNull(),
    name: text().notNull(),
    via: text().notNull(),
    status: text().default('queued').notNull(),
    problem: text(),
    tenantId: uuid('tenant_id'),
    leadId: uuid('lead_id'),
    value: integer(),
    userData: jsonb('user_data').default({}).notNull(),
    pageUrl: text('page_url'),
    test: boolean().default(false).notNull(),
    attempts: smallint().default(0).notNull(),
    sendAfter: timestamp('send_after', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
    sentAt: timestamp('sent_at', { withTimezone: true, mode: 'string' }),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    check('track_events_attempts_check', sql`(attempts >= 0) AND (attempts <= 10)`),
    check('track_events_check', sql`(status = 'sent'::text) = (sent_at IS NOT NULL)`),
    check(
      'track_events_check1',
      sql`(status = ANY (ARRAY['queued'::text, 'sent'::text])) OR (problem IS NOT NULL)`,
    ),
    check(
      'track_events_event_id_check',
      sql`(char_length(event_id) >= 8) AND (char_length(event_id) <= 80)`,
    ),
    check(
      'track_events_name_check',
      sql`name = ANY (ARRAY['PageView'::text, 'Lead'::text, 'CompleteRegistration'::text, 'SubmitApplication'::text, 'StartTrial'::text, 'AddPaymentInfo'::text, 'Subscribe'::text, 'Purchase'::text, 'Contact'::text])`,
    ),
    check('track_events_page_url_check', sql`char_length(page_url) <= 500`),
    check(
      'track_events_problem_check',
      sql`problem = ANY (ARRAY['token_expired'::text, 'rejected'::text, 'timeout'::text, 'no_match_data'::text, 'off'::text])`,
    ),
    check(
      'track_events_status_check',
      sql`status = ANY (ARRAY['queued'::text, 'sent'::text, 'failed'::text, 'skipped'::text])`,
    ),
    check('track_events_user_data_check', sql`jsonb_typeof(user_data) = 'object'::text`),
    check(
      'track_events_user_data_check1',
      sql`NOT (user_data ?| ARRAY['email'::text, 'phone'::text, 'em_raw'::text, 'ph_raw'::text])`,
    ),
    check('track_events_value_check', sql`value >= 0`),
    check(
      'track_events_via_check',
      sql`via = ANY (ARRAY['browser_server'::text, 'server'::text, 'browser'::text])`,
    ),
    foreignKey({
      columns: [table.leadId],
      foreignColumns: [signupLeads.id],
      name: 'track_events_lead_id_fkey',
    }).onDelete('set null'),
    foreignKey({
      columns: [table.tenantId],
      foreignColumns: [tenants.id],
      name: 'track_events_tenant_id_fkey',
    }).onDelete('set null'),
    index('track_events_created_at').using(
      'btree',
      table.createdAt.desc().nullsFirst().op('timestamptz_ops'),
    ),
    index('track_events_lead').using('btree', table.leadId.asc().nullsLast().op('uuid_ops')),
    index('track_events_queue')
      .using('btree', table.sendAfter.asc().nullsLast().op('timestamptz_ops'))
      .where(sql`(status = 'queued'::text)`),
    index('track_events_tenant').using('btree', table.tenantId.asc().nullsLast().op('uuid_ops')),
    unique('track_events_event_id_key').on(table.eventId),
  ],
);

export const variantTemplates = pgTable(
  'variant_templates',
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    tenantId: uuid('tenant_id').notNull(),
    name: text().notNull(),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull(),
    isSample: boolean('is_sample').default(false).notNull(),
  },
  (table) => [
    check(
      'variant_templates_name_check',
      sql`(char_length(name) >= 1) AND (char_length(name) <= 30)`,
    ),
    foreignKey({
      columns: [table.tenantId],
      foreignColumns: [tenants.id],
      name: 'variant_templates_tenant_id_fkey',
    }).onDelete('cascade'),
    index('variant_templates_tenant').using(
      'btree',
      table.tenantId.asc().nullsLast().op('uuid_ops'),
    ),
    unique('variant_templates_tenant_id_id_key').on(table.id, table.tenantId),
  ],
);

export const variantTemplateValues = pgTable(
  'variant_template_values',
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    tenantId: uuid('tenant_id').notNull(),
    templateId: uuid('template_id').notNull(),
    label: text().notNull(),
    sort: integer().default(0).notNull(),
  },
  (table) => [
    check(
      'variant_template_values_label_check',
      sql`(char_length(label) >= 1) AND (char_length(label) <= 30)`,
    ),
    check('variant_template_values_sort_check', sql`sort >= 0`),
    foreignKey({
      columns: [table.templateId, table.tenantId],
      foreignColumns: [variantTemplates.id, variantTemplates.tenantId],
      name: 'variant_template_values_tenant_id_template_id_fkey',
    }).onDelete('cascade'),
    foreignKey({
      columns: [table.tenantId],
      foreignColumns: [tenants.id],
      name: 'variant_template_values_tenant_id_fkey',
    }).onDelete('cascade'),
    index('variant_template_values_tenant').using(
      'btree',
      table.tenantId.asc().nullsLast().op('uuid_ops'),
    ),
    uniqueIndex('variant_template_values_label').using(
      'btree',
      sql`template_id`,
      sql`lower(label)`,
    ),
  ],
);
